```javascript
import * as THREE from 'three/webgpu';
import {
  uniform, color, uv, mix, step, abs, mul, add, sub, smoothstep, min
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.fromArray(config.scenePosition || [0, 0, 0]);
  group.rotation.fromArray(config.sceneRotation || [0, 0, 0]);
  group.scale.fromArray(config.sceneScale || [1, 1, 1]);

  const button = createButtonMesh();
  const labels = createTextLabels(ctx);
  const shadow = createContactShadow();

  group.add(button);
  group.add(labels);
  group.add(shadow);

  group.userData.button = button;
  group.userData.shadow = shadow;

  animateMount(button);

  group.userData.handlers = {
    pointerenter: () => onHoverEnter(button, shadow),
    pointerleave: () => onHoverLeave(button, shadow),
    pointerdown: () => onPress(button),
    pointerup: () => onRelease(button),
  };

  group.userData.cleanup = () => {
    gsap.killTweensOf(button.scale);
    gsap.killTweensOf(button.position);
    gsap.killTweensOf(shadow.material);
    if (button.material.userData.emissiveIntensity) {
      gsap.killTweensOf(button.material.userData.emissiveIntensity);
    }
    button.geometry.dispose();
    button.material.dispose();
    shadow.geometry.dispose();
    shadow.material.dispose();
  };

  return group;
}

function createButtonMesh() {
  const geometry = createRoundedRectGeometry(2.6, 0.68, 0.08, 20);
  const material = createButtonMaterial();
  const mesh = new THREE.Mesh(geometry, material);
  return mesh;
}

function createRoundedRectGeometry(width, height, radius, segments) {
  const shape = new THREE.Shape();
  const w2 = width / 2;
  const h2 = height / 2;

  shape.moveTo(-w2 + radius, -h2);
  shape.lineTo(w2 - radius, -h2);
  shape.quadraticCurveTo(w2, -h2, w2, -h2 + radius);
  shape.lineTo(w2, h2 - radius);
  shape.quadraticCurveTo(w2, h2, w2 - radius, h2);
  shape.lineTo(-w2 + radius, h2);
  shape.quadraticCurveTo(-w2, h2, -w2, h2 - radius);
  shape.lineTo(-w2, -h2 + radius);
  shape.quadraticCurveTo(-w2, -h2, -w2 + radius, -h2);

  const geom = new THREE.ShapeGeometry(shape, segments);
  geom.center();
  return geom;
}

function createButtonMaterial() {
  const uvCoord = uv();
  const emissiveIntensity = uniform(1.6);

  const yNorm = add(mul(uvCoord.y, 1.47), 0.5);

  const col0 = color(0xff4450);
  const col055 = color(0xff2a38);
  const col1 = color(0xc1121f);

  const gradLower = mix(col0, col055, smoothstep(0, 0.55, yNorm));
  const gradUpper = mix(col055, col1, smoothstep(0.55, 1, yNorm));
  const grad = mix(gradLower, gradUpper, step(0.55, yNorm));

  const seamWidth = 0.0147;
  const seamDist = abs(sub(yNorm, 0.5));
  const seam = step(seamDist, seamWidth);
  const gradWithSeam = mix(grad, mul(grad, 0.6), seam);

  const edgeThreshold = 0.022;
  const distX = min(abs(sub(uvCoord.x, -1.3)), abs(sub(uvCoord.x, 1.3)));
  const distY = min(abs(sub(uvCoord.y, -0.34)), abs(sub(uvCoord.y, 0.34)));
  const distEdge = min(distX, distY);
  const isEdge = step(distEdge, edgeThreshold);

  const emissiveColor = mul(color(0xff2a38), emissiveIntensity, isEdge);

  const material = new THREE.MeshStandardNodeMaterial({
    colorNode: gradWithSeam,
    emissiveNode: emissiveColor,
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
  });

  material.userData.emissiveIntensity = emissiveIntensity;
  return material;
}

function createTextLabels(ctx) {
  const group = new THREE.Group();

  if (ctx.fontAtlas && ctx.fontAtlas.renderText) {
    try {
      const mainLabel = ctx.fontAtlas.renderText('BEGIN COMMISSION', {
        fontSize: 20,
        fontWeight: 700,
        letterSpacing: 0.08,
      });
      mainLabel.position.y = 0;
      group.add(mainLabel);

      const caption = ctx.fontAtlas.renderText('NO DEPOSIT REQUIRED', {
        fontSize: 9,
        fontWeight: 400,
        letterSpacing: 0.12,
      });
      caption.position.y = -0.25;
      group.add(caption);
    } catch (e) {
      console.warn('Text rendering unavailable:', e);
    }
  }

  return group;
}

function createContactShadow() {
  const geometry = new THREE.PlaneGeometry(2.6, 0.68);
  const material = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
  });
  const shadow = new THREE.Mesh(geometry, material);
  shadow.position.z = -0.08;
  shadow.renderOrder = -1;
  return shadow;
}

function animateMount(button) {
  button.scale.set(1.04, 1.04, 1.04);
  gsap.to(button.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
}

function onHoverEnter(button, shadow) {
  gsap.to(button.position, {
    z: 0.06,
    duration: 0.18,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });

  if (button.material.userData.emissiveIntensity) {
    gsap.to(button.material.userData.emissiveIntensity, {
      value: 2.2,
      duration: 0.18,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    });
  }

  gsap.to(shadow.material, {
    opacity: 0.5,
    duration: 0.18,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });
}

function onHoverLeave(button, shadow) {
  gsap.to(button.position, {
    z: 0,
    duration: 0.18,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });

  if (button.material.userData.emissiveIntensity) {
    gsap.to(button.material.userData.emissiveIntensity, {
      value: 1.6,
      duration: 0.18,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    });
  }

  gsap.to(shadow.material, {
    opacity: 0.35,
    duration: 0.18,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });
}

function onPress(button) {
  gsap.to(button.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
  });
}

function onRelease(button) {
  gsap.to(button.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.12,
    ease: 'back.out',
  });
}
